<script>
 import {onMount} from 'svelte';import {goto} from '$app/navigation';import {listProjects,listWorkspaces,createProject,deleteProject} from '$lib/api.js';import {notify} from '$lib/stores.js';import Button from '$lib/components/Button.svelte';import Modal from '$lib/components/Modal.svelte';
 let projects=[];let workspaces=[];let selectedOwner='';let loading=true;let saving=false;let showCreate=false;let name='';let description='';
 $: manageableWorkspaces=workspaces.filter(w=>w.can_manage_members);
 async function load(){const [r,w]=await Promise.all([listProjects(),listWorkspaces()]);if(r.ok)projects=r.data.projects||[];else notify(r.error||'Не удалось загрузить проекты','error');if(w.ok){workspaces=w.data.workspaces||[];const allowed=workspaces.filter(x=>x.can_manage_members);if(!allowed.some(x=>String(x.owner_user_id)===String(selectedOwner)))selectedOwner=String(allowed[0]?.owner_user_id||'')}else notify(w.error||'Не удалось загрузить рабочие области','error');loading=false}
 onMount(load);
 async function create(){saving=true;const r=await createProject(name,description,selectedOwner);saving=false;if(!r.ok){notify(r.error||'Не удалось создать проект','error');return}notify('Проект создан','success');showCreate=false;name='';description='';await load()}
 async function remove(p){if(!confirm('Удалить проект? Устройства, сайты и их данные останутся без изменений.'))return;const r=await deleteProject(p.id);if(r.ok){notify('Проект удалён','success');await load()}else notify(r.error||'Ошибка удаления','error')}
</script>
<svelte:head><title>Projects · VELTRIX Dock</title></svelte:head>
<div class="page-header"><div><div class="eyebrow">WORKSPACE</div><h1 class="page-title">Projects</h1><p class="page-desc">Группируйте устройства и сайты по проектам. Удаление проекта не удаляет размещённые ресурсы.</p></div>{#if manageableWorkspaces.length}<Button variant="primary" on:click={()=>showCreate=true}>＋ Новый проект</Button>{/if}</div>
{#if loading}<div class="empty">Загрузка проектов…</div>{:else if !projects.length}<div class="empty"><strong>Пока нет проектов</strong><p>Создайте проект и добавьте в него устройства и сайты.</p>{#if manageableWorkspaces.length}<Button variant="primary" on:click={()=>showCreate=true}>Создать проект</Button>{/if}</div>{:else}
<div class="project-list">{#each projects as p}<article class="project-row"><button class="project-main" on:click={()=>goto('/projects/'+p.id)}><span class="project-icon">▦</span><span class="project-copy"><strong>{p.name}</strong><small>{p.description||p.slug}</small></span><span class="project-stats">{p.device_count} devices · {p.site_count} websites</span><span class="arrow">→</span></button>{#if p.can_manage}<Button variant="ghost" size="sm" on:click={()=>remove(p)}>Удалить</Button>{/if}</article>{/each}</div>{/if}
<Modal open={showCreate} title="Создать проект" onClose={()=>showCreate=false}><div class="field"><label for="project-workspace">Рабочая область</label><select id="project-workspace" class="input" bind:value={selectedOwner}>{#each manageableWorkspaces as w}<option value={String(w.owner_user_id)}>{w.owner_username} · {w.role}</option>{/each}</select></div><div class="field"><label for="project-name">Название</label><input id="project-name" class="input" bind:value={name} maxlength="80" placeholder="Например, Personal websites"/></div><div class="field"><label for="project-desc">Описание</label><textarea id="project-desc" class="input" bind:value={description} rows="3" maxlength="500" placeholder="Краткое описание проекта"/></div><svelte:fragment slot="footer"><Button on:click={()=>showCreate=false}>Отмена</Button><Button variant="primary" loading={saving} disabled={name.trim().length<2} on:click={create}>Создать</Button></svelte:fragment></Modal>
<style>
.eyebrow{font-size:9px;letter-spacing:.14em;color:#818cf8;font-weight:700;margin-bottom:7px}.project-list{border:1px solid #253149;border-radius:12px;background:#101727;overflow:hidden}.project-row{display:flex;align-items:center;gap:10px;padding:10px 13px;border-bottom:1px solid #1e293b}.project-row:last-child{border:0}.project-main{display:flex;align-items:center;gap:11px;flex:1;min-width:0;text-align:left;border:0;background:none;color:#f1f5f9}.project-icon{width:32px;height:32px;border-radius:8px;background:#242b50;color:#a5b4fc;display:grid;place-items:center}.project-copy{display:grid;gap:3px;min-width:0;flex:1}.project-copy strong{font-size:11px}.project-copy small,.project-stats{font-size:9px;color:#64748b;overflow:hidden;text-overflow:ellipsis}.arrow{color:#64748b}.field{display:grid;gap:6px;margin:12px 0}.field label{font-size:10px;color:#94a3b8}.field textarea{resize:vertical}
@media(max-width:600px){.project-stats{display:none}.project-row{padding:9px}}
</style>